-- مرفقات العقود والمستخلصات. يحتفظ النظام بمحتوى الملفات داخل قاعدة البيانات
-- لتدخل ضمن النسخ الاحتياطي والاستعادة. في التشغيل المعتاد ينشئ ensure_schema الجدول تلقائيًا.
CREATE TABLE IF NOT EXISTS "ContractAttachments" (
  "AttachmentId" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ContractId" INTEGER NULL REFERENCES "Contracts"("ContractId") ON DELETE CASCADE,
  "SettlementId" INTEGER NULL REFERENCES "ContractSettlements"("SettlementId") ON DELETE CASCADE,
  "Category" VARCHAR(80) NOT NULL DEFAULT 'Other',
  "OriginalFilename" VARCHAR(255) NOT NULL,
  "ContentType" VARCHAR(120) NOT NULL DEFAULT 'application/octet-stream',
  "SizeBytes" INTEGER NOT NULL CHECK ("SizeBytes" > 0),
  "FileContent" BYTEA NOT NULL,
  "Notes" VARCHAR(500) NULL,
  "UploadedBy" INTEGER NULL REFERENCES "Users"("UserId"),
  "UploadedAt" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "CK_ContractAttachments_OneParent" CHECK (
    ("ContractId" IS NOT NULL AND "SettlementId" IS NULL) OR
    ("ContractId" IS NULL AND "SettlementId" IS NOT NULL)
  )
);
CREATE INDEX IF NOT EXISTS "IX_ContractAttachments_ContractId" ON "ContractAttachments" ("ContractId");
CREATE INDEX IF NOT EXISTS "IX_ContractAttachments_SettlementId" ON "ContractAttachments" ("SettlementId");
